// and exactly one of them is ever set. A refusal reaches no column,
// findings having nowhere to put a finding that was not made, so it
// travels here and the group that closes this pass is what records that
// there was one.
return [{
  json: {
    domain_id: recorded.domain_id,
    source_id: recorded.source_id,
    document_id: recorded.document_id,
    document_stored: recorded.document_stored,
    store_error: recorded.store_error,
    contract_version: recorded.contract_version,
    contract_version_accepted: recorded.contract_version_accepted,
    envelope_accepted: recorded.envelope_accepted,
    config_errors: configErrors,
    record: built === null ? null : built.record,
    warnings,
    parse_status: parseStatus,
    parse_error: parseError,
    finding_fields: finding.fields,
    finding_refusal: finding.fields === null && finding.faults.length > 0
      ? finding.faults.join(PARSE_ERROR_JOIN)
      : null,
  },
}];

